(function(){
 const shared=document.body.classList.contains('shared-app'),q=s=>document.querySelector(s);let stack=[],last=shared?scope:view,restoring=false;
 q('.desk-project-preview')?.remove();q('#deskManage [data-desk-view="reports"]')?.remove();const team=q('#deskManage [data-desk-view="members"] span');if(team)team.textContent='تیم پروژه';
 const back=document.createElement('button');back.type='button';back.className='app-back';back.id='appBack';back.innerHTML='<span>→</span> بازگشت';q('.desk-top-context').prepend(back);
 function sync(){if(window.SAMANDIS_PERSONAL_MODE){back.disabled=false;back.title='بازگشت به '+(shared?(project?.name||'پروژه تیمی'):'پروژه دارایی');return}const current=shared?scope:view,dialog=document.querySelector('dialog[open]');back.disabled=!dialog&&!stack.length&&(current==='mine');back.title=dialog?'بستن پنجره و برگشت به فهرست':'بازگشت به نمای قبلی'}
 back.onclick=()=>{const dialogs=Array.from(document.querySelectorAll('dialog[open]'));if(dialogs.length){const d=dialogs.at(-1),close=d.querySelector('#closeTask,#sharedClose');if(close)close.click();else d.close();document.body.classList.remove('task-drawer-open');sync();return}const next=stack.pop()||'mine';restoring=true;if(shared){scope=next;phase='all';search='';render()}else navigate(next);restoring=false;sync()};
 const previous=render;render=function(){const current=shared?scope:view;if(current!==last){if(!restoring)stack.push(last);last=current}previous();q('.team-subnav')?.remove();if(['members','reports'].includes(current)){
 q('#deskCrumb').textContent='تیم پروژه';q('#deskManage [data-desk-view="members"]')?.classList.add('active');const root=q(shared?'#sharedContent':'#workspace');if(root){const nav=document.createElement('div');nav.className='team-subnav team-tab-picker';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','بخش‌های تیم پروژه');nav.innerHTML='<button data-team="reports" class="'+(current==='reports'?'selected':'')+'">گزارش‌ها و کارکرد</button><button data-team="members" class="'+(current==='members'?'selected':'')+'">اعضا و دسترسی‌ها</button>';root.before(nav);nav.querySelectorAll('button').forEach(b=>{const selected=b.dataset.team===current;b.type='button';b.setAttribute('role','tab');b.setAttribute('aria-selected',String(selected));b.setAttribute('aria-controls',root.id);b.tabIndex=selected?0:-1;const icon=b.dataset.team==='reports'?'<path d="M4 20V4m0 16h16M9 16v-5m5 5V7m5 9V4"/>':'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2m1-15a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>';b.innerHTML='<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true">'+icon+'</svg><span>'+b.textContent+'</span>';b.onclick=()=>{if(shared){scope=b.dataset.team;render()}else navigate(b.dataset.team)};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?'reports':e.key==='End'?'members':b.dataset.team==='reports'?'members':'reports';if(shared){scope=next;render()}else navigate(next);document.querySelector('[data-team="'+next+'"]').focus()}})}}
 const teamEntry=q('#deskManage [data-desk-view="members"]');if(teamEntry)teamEntry.onclick=()=>{if(shared){scope=management()?'reports':'members';render()}else navigate('reports')};sync();};
 document.querySelectorAll('dialog').forEach(d=>new MutationObserver(sync).observe(d,{attributes:true,attributeFilter:['open']}));render();
})();
